from abc import ABC, abstractproperty, abstractmethod
from collections import deque
from datetime import datetime, timedelta
from time import sleep
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError
import logging

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class StreamsDuplicated(Exception):
    pass


class StreamDoesNotExist(Exception):
    pass


class Rule(ABC):
    @abstractproperty
    def condition(self):
        raise NotImplementedError

    @abstractmethod
    def meets_condition(self, *args, **kwargs):
        raise NotImplementedError


class MessageRule(Rule):
    condition = None

    def __init__(self, condition):
        """

        :param Tuple[NotificationMsg] condition:
        """
        self.condition = condition

    def meets_condition(self, message):
        if type(message) in self.condition:
            return True

        if isinstance(message, self.condition):
            return True
        return False


class Stream(ABC):

    @abstractproperty
    def name(self):
        raise NotImplementedError

    @abstractproperty
    def rule(self):
        raise NotImplementedError

    @abstractproperty
    def data(self):
        raise NotImplementedError

    @abstractmethod
    def matches(self, *args, **kwargs):
        raise NotImplementedError

    @abstractmethod
    def put(self, *args, **kwargs):
        raise NotImplementedError

    @abstractmethod
    def get(self, *args, **kwargs):
        raise NotImplementedError


class MessageStream(Stream):
    name = None
    rule = None
    data = None

    def __init__(self, name, rule, size=1000, msg_interval=0.1):
        self.rule = rule
        self.name = name
        self.size = size
        self.data = deque(maxlen=size)
        self.msg_interval = msg_interval

    def matches(self, message):
        return self.rule.meets_condition(message=message)

    def put(self, message):
        self.data.append(message)

    def get(self, timeout):
        log.info("Fetching message from stream: {}".format(self.name))
        start_time = datetime.now()
        while True:
            try:
                return self.data.popleft()
            except IndexError:
                if datetime.now() - start_time > timedelta(seconds=timeout):
                    raise StreamTimeoutError("Getting message from stream {} timed out".format(self.name))
                sleep(self.msg_interval)


class Filter(ABC):
    @abstractproperty
    def name(self):
        raise NotImplementedError

    @abstractproperty
    def stream_map(self):
        raise NotImplementedError

    def __init__(self, streams):
        self._create_stream_map(msg_streams=streams)

    def _create_stream_map(self, msg_streams):
        for stream in msg_streams:
            if stream.name in self.stream_map:
                error_msg = "Stream of name: {stream_name} already exists in filter: {filter_name}"
                raise StreamsDuplicated(error_msg.format(stream_name=stream.name, filter_name=self.name))
            self.stream_map[stream.name] = stream

    def update_streams(self, msg_streams, overwrite=False):
        for stream in msg_streams:
            if stream.name in self.stream_map and overwrite is False:
                error_msg = "By default you cannot replace existing stream: {stream_name} in filter: {filter_name}"
                raise StreamsDuplicated(error_msg.format(stream_name=stream.name, filter_name=self.name))
            self.stream_map[stream.name] = stream

    def remove_streams(self, msg_streams):
        for stream in msg_streams:
            if stream.name not in self.stream_map:
                error_msg = "Stream you want to remove: {stream_name} does not exist in filter: {filter_name}"
                raise ValueError(error_msg.format(stream_name=stream.name, filter_name=self.name))
            self.stream_map.pop(stream.name)


class MessageFilter(Filter):
    name = None
    stream_map = None

    def __init__(self, name, streams):
        self.name = name
        self.stream_map = {}
        super(MessageFilter, self).__init__(streams=streams)

    def get_message(self, stream_name, timeout=5):
        stream = self.stream_map.get(stream_name)

        if stream is None:
            error_msg = "Stream of name: {stream_name} does not exist in filter: {filter_name}"
            raise StreamDoesNotExist(error_msg.format(stream_name=stream_name, filter_name=self.name))

        return stream.get(timeout=timeout)

    def put_message(self, message):
        for stream in self.stream_map.values():
            if stream.matches(message=message):
                info_msg = "Message : {message} is put into: filter: {filter_name}, stream: {stream_name}"
                log.info(info_msg.format(message=message, filter_name=self.name, stream_name=stream.name))
                stream.put(message=message)

    def get_streams(self):
        return list(self.stream_map.values())
